() => {
  const el = document.querySelector('input.dz-hidden-input');
  if (!el) return {err: 'no input'};
  el.style.cssText = 'display:block!important;opacity:1;width:240px;height:48px;position:relative;z-index:9999;';
  el.setAttribute('aria-label', 'apk-file-input');
  el.removeAttribute('hidden');
  return {ok: true, accept: el.accept};
}
